function calculateBackoffDelay(attempt: number, baseDelayMs: number, maxDelayMs: number, jitterRatio: number = 0.5): number {
  const raw = baseDelayMs * Math.pow(2, attempt) * (1 + jitterRatio);
  return Math.min(maxDelayMs, Math.round(raw));
}

aideploy-web-assign-day-1:
function classifyModelApiStatus(statusCode: number, retryAfterHeader?: number): { retryable: boolean; delayMs: number; errorType: 'RATE_LIMIT' | 'SERVER_OVERLOAD' | 'CLIENT_ERROR' | 'FATAL' | 'SUCCESS' } {
  if (statusCode === 200) {
    return { retryable: false, delayMs: 0, errorType: 'SUCCESS' };
  }
  if (statusCode === 429) {
    const delayMs = retryAfterHeader !== undefined ? retryAfterHeader * 1000 : 1000;
    return { retryable: true, delayMs, errorType: 'RATE_LIMIT' };
  }
  if (statusCode === 503 || statusCode === 502 || statusCode === 504) {
    return { retryable: true, delayMs: 2000, errorType: 'SERVER_OVERLOAD' };
  }
  if (statusCode >= 400 && statusCode < 500) {
    return { retryable: false, delayMs: 0, errorType: 'CLIENT_ERROR' };
  }
  return { retryable: false, delayMs: 0, errorType: 'FATAL' };
}

