function extractJsonFromMarkdownFence(rawResponse: string): { parsed: Record<string, any> | null; success: boolean; error?: string } {
  const fenceMatch = rawResponse.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenceMatch ? fenceMatch[1].trim() : rawResponse.trim();
  try {
    const parsed = JSON.parse(candidate);
    if (parsed && typeof parsed === 'object') {
      return { parsed, success: true };
    }
    return { parsed: null, success: false, error: 'Parsed entity is not an object' };
  } catch (err: any) {
    return { parsed: null, success: false, error: err.message };
  }
}

