function calculateInferenceCost(modelTier: 'small' | 'medium' | 'frontier', promptTokens: number, completionTokens: number): { promptCost: number; completionCost: number; totalCost: number } {
  const rates = {
    small: { prompt: 0.15, comp: 0.60 },
    medium: { prompt: 0.50, comp: 1.50 },
    frontier: { prompt: 5.00, comp: 15.00 }
  };
  const r = rates[modelTier];
  const pCost = Math.round((promptTokens * r.prompt / 1e6) * 1e6) / 1e6;
  const cCost = Math.round((completionTokens * r.comp / 1e6) * 1e6) / 1e6;
  const total = Math.round((pCost + cCost) * 1e6) / 1e6;
  return { promptCost: pCost, completionCost: cCost, totalCost: total };
}

