function auditMonthlyAiSpend(currentSpend: number, projectedDailySpend: number, remainingDaysInMonth: number, hardCap: number): { projectedTotal: number; willExceed: boolean; budgetRemaining: number; burnRateRatio: number } {
  const projectedTotal = Math.round((currentSpend + (projectedDailySpend * remainingDaysInMonth)) * 100) / 100;
  const willExceed = projectedTotal > hardCap;
  const budgetRemaining = Math.max(0, Math.round((hardCap - currentSpend) * 100) / 100);
  const burnRateRatio = hardCap > 0 ? Math.round((projectedTotal / hardCap) * 100) / 100 : 0;
  return { projectedTotal, willExceed, budgetRemaining, burnRateRatio };
}

