function interpolatePromptTemplate(template: string, variables: Record<string, string>): { prompt: string; missingVariables: string[]; replacedCount: number } {
  const missing = new Set<string>();
  let count = 0;
  const prompt = template.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (_, key) => {
    if (key in variables) {
      count++;
      return variables[key];
    }
    missing.add(key);
    return `{{${key}}}`;
  });
  return { prompt, missingVariables: Array.from(missing).sort(), replacedCount: count };
}

aideploy-web-assign-day-5:
function sanitizePromptVariables(input: string, forbiddenDelimiters: string[] = ['```', '###', '---', '<|im_end|>']): { sanitized: string; escapedCount: number; hasViolations: boolean } {
  let sanitized = input;
  let escapedCount = 0;
  for (const delim of forbiddenDelimiters) {
    const escapedDelim = delim.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    const re = new RegExp(escapedDelim, 'g');
    const matches = sanitized.match(re);
    if (matches) {
      escapedCount += matches.length;
      sanitized = sanitized.replace(re, '[REDACTED_DELIMITER]');
    }
  }
  return { sanitized, escapedCount, hasViolations: escapedCount > 0 };
}

