function parseSseLine(line: string): { isDone: boolean; content: string | null; id?: string } {
  const trimmed = line.trim();
  if (!trimmed.startsWith('data:')) {
    return { isDone: false, content: null };
  }
  const payload = trimmed.slice(5).trim();
  if (payload === '[DONE]') {
    return { isDone: true, content: null };
  }
  try {
    const parsed = JSON.parse(payload);
    const id = parsed.id;
    const content = parsed.choices && parsed.choices[0] && parsed.choices[0].delta ? (parsed.choices[0].delta.content ?? null) : null;
    return { isDone: false, content, id };
  } catch {
    return { isDone: false, content: null };
  }
}

