  const totalDurationMs = Math.max(0, finishMs - requestStartMs);
  const durationSec = totalDurationMs / 1000;
  const tokensPerSecond = durationSec > 0 ? Math.round((totalTokens / durationSec) * 100) / 100 : 0;
  return { ttftMs, totalDurationMs, tokensPerSecond };
}

