class MicroBatchQueue<T> {
  private queue: T[] = [];
  private firstTimestamp: number | null = null;
  constructor(public maxBatchSize: number, public maxLingerMs: number) {}
  enqueue(item: T, timestampMs: number): { shouldFlush: boolean; batch: T[] | null } {
    if (this.queue.length === 0) {
      this.firstTimestamp = timestampMs;
    }
    this.queue.push(item);
    const sizeTrigger = this.queue.length >= this.maxBatchSize;
    const timeTrigger = this.firstTimestamp !== null && (timestampMs - this.firstTimestamp >= this.maxLingerMs);
    if (sizeTrigger || timeTrigger) {
      const batch = [...this.queue];
      this.queue = [];
      this.firstTimestamp = null;
      return { shouldFlush: true, batch };
    }
    return { shouldFlush: false, batch: null };
  }
}

