function calculateBatchEfficiency(totalIndividualRequests: number, batchCount: number): { apiCallReductionPercent: number; avgBatchSize: number } {
  if (totalIndividualRequests <= 0 || batchCount <= 0) {
    return { apiCallReductionPercent: 0, avgBatchSize: 0 };
  }
  const apiCallReductionPercent = Math.round((1 - (batchCount / totalIndividualRequests)) * 100 * 100) / 100;
  const avgBatchSize = Math.round((totalIndividualRequests / batchCount) * 100) / 100;
  return { apiCallReductionPercent, avgBatchSize };
}

aideploy-web-exam-day-8:
function vectorNormAndDotProduct(vecA: number[], vecB: number[]): { dotProduct: number; normA: number; normB: number } {
  if (vecA.length !== vecB.length || vecA.length === 0) {
    return { dotProduct: 0, normA: 0, normB: 0 };
  }
  let dot = 0;
  let sumA = 0;
  let sumB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    sumA += vecA[i] * vecA[i];
    sumB += vecB[i] * vecB[i];
  }
  const normA = Math.round(Math.sqrt(sumA) * 10000) / 10000;
  const normB = Math.round(Math.sqrt(sumB) * 10000) / 10000;
  return { dotProduct: Math.round(dot * 10000) / 10000, normA, normB };
}

aideploy-web-assign-day-8:
function computeCosineSimilarity(vecA: number[], vecB: number[]): number {
  if (vecA.length !== vecB.length || vecA.length === 0) return 0;
  let dot = 0;
  let sumA = 0;
  let sumB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    sumA += vecA[i] * vecA[i];
    sumB += vecB[i] * vecB[i];
  }
  if (sumA === 0 || sumB === 0) return 0;
  const sim = dot / (Math.sqrt(sumA) * Math.sqrt(sumB));
  return Math.round(sim * 10000) / 10000;
}

aideploy-web-exam-day-9:
class SemanticVectorCache {
  private items: { key: string; embedding: number[]; response: string }[] = [];
  set(key: string, embedding: number[], response: string): void {
    this.items.push({ key, embedding, response });
  }
  findClosest(queryEmbedding: number[], minSimilarity: number): { hit: boolean; key?: string; response?: string; similarity?: number } {
    let bestSim = -1;
    let bestItem: { key: string; embedding: number[]; response: string } | null = null;
    for (const item of this.items) {
      const sim = this.cosineSim(item.embedding, queryEmbedding);
      if (sim > bestSim) {
        bestSim = sim;
        bestItem = item;
      }
    }
    if (bestItem && bestSim >= minSimilarity) {
      return { hit: true, key: bestItem.key, response: bestItem.response, similarity: Math.round(bestSim * 10000) / 10000 };
    }
    return { hit: false };
  }
  private cosineSim(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;
    let dot = 0, sa = 0, sb = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      sa += a[i] * a[i];
      sb += b[i] * b[i];
    }
    if (sa === 0 || sb === 0) return 0;
    return dot / (Math.sqrt(sa) * Math.sqrt(sb));
  }
}

