function calculateModelMemory(parameterCountBillions: number, quantBitWidth: 32 | 16 | 8 | 4): { weightMemoryGB: number; recommendedVramGB: number } {
  const bytesPerParam = quantBitWidth / 8;
  const totalBytes = parameterCountBillions * 1e9 * bytesPerParam;
  const weightGB = totalBytes / (1024 * 1024 * 1024);
  const weightMemoryGB = Math.round(weightGB * 100) / 100;
  const recommendedVramGB = Math.round((weightMemoryGB * 1.2) * 100) / 100;
  return { weightMemoryGB, recommendedVramGB };
}

