function calculateKvCacheMemory(batchSize: number, contextLength: number, numLayers: number, numHeads: number, headDim: number, precisionBytes: number = 2): { kvCacheBytes: number; kvCacheMB: number } {
  // 2 for K and V vectors
  const bytesPerTokenPerLayer = 2 * numHeads * headDim * precisionBytes;
  const kvCacheBytes = bytesPerTokenPerLayer * numLayers * batchSize * contextLength;
  const kvCacheMB = Math.round((kvCacheBytes / (1024 * 1024)) * 100) / 100;
  return { kvCacheBytes, kvCacheMB };
}

