aideploy-web-assign-day-15:
function calculateRequiredGpuReplicas(totalTokensPerSec: number, singleGpuTokensPerSec: number, targetUtilization: number = 0.75): { minimumReplicas: number; totalCapacityTokensPerSec: number; headroomPercent: number } {
  if (totalTokensPerSec <= 0 || singleGpuTokensPerSec <= 0) {
    return { minimumReplicas: 0, totalCapacityTokensPerSec: 0, headroomPercent: 0 };
  }
  const effectiveGpuThroughput = singleGpuTokensPerSec * targetUtilization;
  const minimumReplicas = Math.ceil(totalTokensPerSec / effectiveGpuThroughput);
  const totalCapacityTokensPerSec = minimumReplicas * singleGpuTokensPerSec;
  const headroomPercent = Math.round(((totalCapacityTokensPerSec - totalTokensPerSec) / totalCapacityTokensPerSec) * 100 * 100) / 100;
  return { minimumReplicas, totalCapacityTokensPerSec, headroomPercent };
}
